1	//! Interactive prompts.
2	
3	use console::{style, Key, Style, Term};
4	use dialoguer::theme::ColorfulTheme;
5	use dialoguer::{Confirm, Input, MultiSelect, Select};
6	
7	use crate::error::{BivvyError, Result};
8	
9	use super::{Prompt, PromptOption, PromptResult, PromptType};
10	
11	/// Convert dialoguer errors to BivvyError.
12	fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
13	    BivvyError::Io(e.into())
14	}
15	
16	/// Dialoguer theme without the default yellow `?` prefix.
17	fn prompt_theme() -> ColorfulTheme {
18	    ColorfulTheme {
19	        prompt_prefix: style("".to_string()),
20	        ..ColorfulTheme::default()
21	    }
22	}
23	
24	/// Check for an environment variable override for a prompt.
25	///
26	/// Users can skip any prompt by setting an env var matching the prompt key:
27	///   `BUMP=minor bivvy run --workflow release`
28	///
29	/// The lookup is case-insensitive on the key side: a prompt with key "bump"
30	/// matches env var `BUMP`, `bump`, or `Bump`.
31	pub(crate) fn env_override(prompt: &Prompt) -> Option<PromptResult> {
32	    let env_key = prompt.key.to_uppercase();
33	    let value = std::env::var(&env_key).ok()?;
34	
35	    let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
36	    if is_multiselect {
37	        let values: Vec<String> = value.split(',').map(|s| s.trim().to_string()).collect();
38	        Some(PromptResult::Strings(values))
39	    } else {
40	        Some(PromptResult::String(value))
41	    }
42	}
43	
44	/// Prompt the user for input.
45	///
46	/// Before showing any interactive prompt, checks for an environment variable
47	/// matching the prompt key (e.g., `BUMP=minor` for a prompt with key "bump").
48	/// This works in both interactive and non-interactive modes.
49	pub fn prompt_user(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
50	    if let Some(result) = env_override(prompt) {
51	        return Ok(result);
52	    }
53	
54	    match &prompt.prompt_type {
55	        PromptType::Confirm => prompt_confirm(prompt, term),
56	        PromptType::Input => prompt_input(prompt, term),
57	        PromptType::Select { options } => prompt_select(prompt, options, term),
58	        PromptType::MultiSelect { options } => prompt_multiselect(prompt, options, term),
59	    }
60	}
61	
62	fn prompt_confirm(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
63	    let default = prompt
64	        .default
65	        .as_ref()
66	        .map(|s| s.to_lowercase() == "true" || s == "y" || s == "yes")
67	        .unwrap_or(true);
68	
69	    let result = Confirm::new()
70	        .with_prompt(&prompt.question)
71	        .default(default)
72	        .interact_on(term)
73	        .map_err(map_dialoguer_err)?;
74	
75	    Ok(PromptResult::Bool(result))
76	}
77	
78	fn prompt_input(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
79	    let input = Input::<String>::new().with_prompt(&prompt.question);
80	
81	    let result: String = if let Some(default) = &prompt.default {
82	        input
83	            .default(default.clone())
84	            .interact_on(term)
85	            .map_err(map_dialoguer_err)?
86	    } else {
87	        input.interact_on(term).map_err(map_dialoguer_err)?
88	    };
89	
90	    Ok(PromptResult::String(result))
91	}
92	
93	/// Dialoguer theme for general select prompts with `›`/`·` indicators.
94	fn select_theme() -> ColorfulTheme {
95	    ColorfulTheme {
96	        prompt_prefix: style("".to_string()),
97	        prompt_suffix: style("".to_string()),
98	        success_prefix: style("".to_string()),
99	        success_suffix: style("·".to_string()).for_stderr().dim(),
100	        active_item_prefix: style("›".to_string()).for_stderr().bold(),
101	        inactive_item_prefix: style("·".to_string()).for_stderr().dim(),
102	        active_item_style: Style::new().for_stderr().bold(),
103	        inactive_item_style: Style::new().for_stderr().dim(),
104	        values_style: Style::new().for_stderr().bold(),
105	        ..ColorfulTheme::default()
106	    }
107	}
108	
109	/// Check if options form a yes/no pair.
110	fn is_yes_no(options: &[PromptOption]) -> bool {
111	    options.len() == 2
112	        && options.iter().any(|o| o.value == "yes")
113	        && options.iter().any(|o| o.value == "no")
114	}
115	
116	fn prompt_select(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
117	    // Use custom yes/no prompt for y/n keyboard shortcut support.
118	    // Requires a real TTY — prompt_yes_no uses term.read_key() directly.
119	    // On non-TTY, fall through to dialoguer's Select.
120	    //
121	    // Terminal foreground group is claimed in main.rs via tcsetpgrp(),
122	    // so read_key() works even when launched via `cargo run`.
123	    if is_yes_no(options) && term.is_term() {
124	        return prompt_yes_no(prompt, options, term);
125	    }
126	
127	    // Dumb terminals don't support cursor movement, so dialoguer's
128	    // clear-and-repaint cycles produce non-deterministic garbage.
129	    // Use a forward-only renderer instead.
130	    if super::is_dumb_term() && term.is_term() {
131	        return prompt_select_dumb(prompt, options, term);
132	    }
133	
134	    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();
135	
136	    let default_idx = prompt
137	        .default
138	        .as_ref()
139	        .and_then(|d| options.iter().position(|o| o.value == *d))
140	        .unwrap_or(0);
141	
142	    let selection = Select::with_theme(&select_theme())
143	        .with_prompt(&prompt.question)
144	        .items(&labels)
145	        .default(default_idx)
146	        .interact_on(term)
147	        .map_err(map_dialoguer_err)?;
148	
149	    Ok(PromptResult::String(options[selection].value.clone()))
150	}
151	
152	/// Forward-only select prompt for dumb terminals.
153	///
154	/// Renders options once, accepts arrow keys and Enter without redrawing.
155	/// No cursor-movement sequences are emitted, so PTY output is deterministic.
156	fn prompt_select_dumb(
157	    prompt: &Prompt,
158	    options: &[PromptOption],
159	    term: &Term,
160	) -> Result<PromptResult> {
161	    let default_idx = prompt
162	        .default
163	        .as_ref()
164	        .and_then(|d| options.iter().position(|o| o.value == *d))
165	        .unwrap_or(0);
166	
167	    let mut sel = default_idx;
168	
169	    let _raw_guard = RawModeGuard::enter(term).map_err(BivvyError::Io)?;
170	
171	    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
172	
173	    for (i, opt) in options.iter().enumerate() {
174	        let line = if i == sel {
175	            format!("  › {}", opt.label)
176	        } else {
177	            format!("  · {}", opt.label)
178	        };
179	        term.write_line(&line).map_err(BivvyError::Io)?;
180	    }
181	    term.flush().map_err(BivvyError::Io)?;
182	
183	    loop {
184	        let key = term.read_key().map_err(BivvyError::Io)?;
185	
186	        match key {
187	            Key::Enter | Key::Char(' ') => {
188	                drop(_raw_guard);
189	                term.write_line(&format!("  › {}", options[sel].label))
190	                    .map_err(BivvyError::Io)?;
191	                return Ok(PromptResult::String(options[sel].value.clone()));
192	            }
193	            Key::ArrowDown | Key::Tab | Key::Char('j') => {
194	                sel = (sel + 1) % options.len();
195	            }
196	            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
197	                sel = (sel + options.len() - 1) % options.len();
198	            }
199	            _ => {}
200	        }
201	    }
202	}
203	
204	/// RAII guard that restores the terminal cursor when dropped.
205	///
206	/// Ensures the cursor is shown even if the process panics or is
207	/// interrupted (Ctrl+C) while the cursor is hidden during a prompt.
208	struct CursorGuard<'a> {
209	    term: &'a Term,
210	}
211	
212	impl<'a> CursorGuard<'a> {
213	    fn new(term: &'a Term) -> std::io::Result<Self> {
214	        term.hide_cursor()?;
215	        Ok(Self { term })
216	    }
217	}
218	
219	impl Drop for CursorGuard<'_> {
220	    fn drop(&mut self) {
221	        self.term.show_cursor().ok();
222	    }
223	}
224	
225	/// RAII guard that sets the terminal to raw mode and restores on drop.
226	///
227	/// On macOS, characters that arrive while the terminal is in canonical
228	/// (cooked) mode are stored in the canonical editing buffer. When
229	/// `tcsetattr` switches to raw mode (ICANON off), macOS does NOT make
230	/// those buffered characters available for non-canonical reads — they
231	/// are effectively lost. This is a macOS kernel behavior difference
232	/// from Linux.
233	///
234	/// By setting raw mode before any prompt output, keystrokes that arrive
235	/// at any point during the prompt are always in the raw input queue and
236	/// immediately available for `read_key()`.
237	#[cfg(unix)]
238	struct RawModeGuard {
239	    fd: i32,
240	    original: libc::termios,
241	}
242	
243	#[cfg(unix)]
244	impl RawModeGuard {
245	    fn enter(term: &Term) -> std::io::Result<Self> {
246	        use std::os::unix::io::AsRawFd;
247	        let fd = term.as_raw_fd();
248	
249	        unsafe {
250	            let mut original = std::mem::MaybeUninit::<libc::termios>::uninit();
251	            if libc::tcgetattr(fd, original.as_mut_ptr()) != 0 {
252	                return Err(std::io::Error::last_os_error());
253	            }
254	            let original = original.assume_init();
255	
256	            let mut raw = original;
257	            libc::cfmakeraw(&mut raw);
258	            // Preserve output processing so \n maps to \r\n in prompt text.
259	            raw.c_oflag = original.c_oflag;
260	
261	            if libc::tcsetattr(fd, libc::TCSADRAIN, &raw) != 0 {
262	                return Err(std::io::Error::last_os_error());
263	            }
264	
265	            Ok(Self { fd, original })
266	        }
267	    }
268	}
269	
270	#[cfg(unix)]
271	impl Drop for RawModeGuard {
272	    fn drop(&mut self) {
273	        unsafe {
274	            libc::tcsetattr(self.fd, libc::TCSADRAIN, &self.original);
275	        }
276	    }
277	}
278	
279	#[cfg(not(unix))]
280	struct RawModeGuard;
281	
282	#[cfg(not(unix))]
283	impl RawModeGuard {
284	    fn enter(_term: &Term) -> std::io::Result<Self> {
285	        Ok(Self)
286	    }
287	}
