337	    fn render_help_overlay(&self, frame: &mut Frame, area: Rect) {
338	        let bindings = self.bindings();
339	        let footer = bindings.footer_bindings();
340	
341	        // Build help lines
342	        let mut lines: Vec<Line> = Vec::new();
343	        lines.push(Line::default()); // blank line after title
344	        for binding in &footer {
345	            lines.push(Line::from(vec![
346	                Span::styled(
347	                    format!("{:<12}", binding.key_label),
348	                    Style::default()
349	                        .fg(Palette::LIME)
350	                        .add_modifier(Modifier::BOLD),
351	                ),
352	                Span::styled(binding.description, Style::default().fg(Palette::TEXT)),
353	            ]));
354	        }
355	        lines.push(Line::default()); // blank line before close hint
356	        lines.push(Line::styled(
357	            "Press any key to close",
358	            Style::default().fg(Palette::TEXT_DIM),
359	        ));
360	
361	        let content_height = lines.len() as u16 + 2; // +2 for border
362	        let content_width = 36u16;
363	
364	        let overlay_width = content_width.min(area.width.saturating_sub(4));
365	        let overlay_height = content_height.min(area.height.saturating_sub(2));
366	
367	        let x = area.x + (area.width.saturating_sub(overlay_width)) / 2;
368	        let y = area.y + (area.height.saturating_sub(overlay_height)) / 2;
369	
370	        let overlay_area = Rect::new(x, y, overlay_width, overlay_height);
371	
372	        // Clear background
373	        frame.render_widget(Clear, overlay_area);
374	
375	        let block = Block::default()
376	            .borders(Borders::ALL)
377	            .border_type(ratatui::widgets::BorderType::Rounded)
378	            .border_style(Style::default().fg(Palette::LIME))
379	            .title(" Help ")
380	            .title_style(
381	                Style::default()
382	                    .fg(Palette::LIME)
383	                    .add_modifier(Modifier::BOLD),
384	            )
385	            .style(Style::default().bg(Palette::BG_ELEVATED));
386	
387	        let inner = block.inner(overlay_area);
388	        frame.render_widget(block, overlay_area);
389	
390	        // Render lines inside the block
391	        for (i, line) in lines.iter().enumerate() {
392	            let ly = inner.y + i as u16;
393	            if ly >= inner.y + inner.height {
394	                break;
395	            }
396	            frame
397	                .buffer_mut()
398	                .set_line(inner.x + 1, ly, line, inner.width.saturating_sub(2));
399	        }
400	    }
