598	        }
599	
600	        let selected_steps = self.get_selected_steps();
601	        let step_count = selected_steps.len();
602	        let total_count = self.step_templates.len();
603	
604	        // Two column grid
605	        let col_width = inner.width / 2;
606	        let y = inner.y;
607	
608	        // Column 1: Selected Steps
609	        frame.buffer_mut().set_string(
610	            inner.x,
611	            y,
612	            "Selected Steps",
613	            Style::default().fg(Palette::TEXT_DIM),
614	        );
615	        let steps_display = if step_count == 0 {
616	            "none".to_string()
617	        } else {
618	            format!("{} of {}", step_count, total_count)
619	        };
620	        frame.buffer_mut().set_string(
621	            inner.x,
622	            y + 1,
623	            &steps_display,
624	            Style::default()
625	                .fg(if step_count > 0 {
626	                    Palette::TEAL
627	                } else {
628	                    Palette::TEXT_MUTED
629	                })
630	                .add_modifier(Modifier::BOLD),
631	        );
632	
633	        // Column 2: Step names (if any selected)
634	        frame.buffer_mut().set_string(
635	            inner.x + col_width,
636	            y,
637	            "Templates",
638	            Style::default().fg(Palette::TEXT_DIM),
639	        );
640	        let names = if selected_steps.is_empty() {
641	            "—".to_string()
642	        } else {
643	            selected_steps.join(", ")
644	        };
645	        // Truncate if too long
646	        let max_len = (col_width as usize).saturating_sub(1);
647	        let names_display = if names.len() > max_len {
648	            format!("{}…", &names[..max_len.saturating_sub(1)])
649	        } else {
650	            names
651	        };
652	        frame.buffer_mut().set_string(
653	            inner.x + col_width,
654	            y + 1,
655	            &names_display,
656	            Style::default().fg(Palette::TEXT),
657	        );
658	    }
659	}
