667	impl Screen for InitScreen {
668	    fn render(&self, frame: &mut Frame, area: Rect, _app_state: &AppState, hits: &mut HitMap) {
669	        // Clear with main background
670	        frame
671	            .buffer_mut()
672	            .set_style(area, Style::default().bg(Palette::BG));
673	
674	        // Global padding (2 columns horizontal, 1 row vertical)
675	        let padded = Rect {
676	            x: area.x + 2,
677	            y: area.y + 1,
678	            width: area.width.saturating_sub(4),
679	            height: area.height.saturating_sub(2),
680	        };
681	
682	        // 1. Get vertical region definitions from screen_layouts
683	        let regions = screen_layouts::init();
684	
685	        // 2. Allocate heights
686	        let allocations = allocate_regions(padded.height, &regions);
687	
688	        // 3. Compute Rect + DegradeMode for each region
689	        let mut y = padded.y;
690	        let mut region_areas: Vec<(&str, Rect, DegradeMode)> = Vec::new();
691	        for alloc in &allocations {
692	            let rect = Rect::new(padded.x, y, padded.width, alloc.height);
693	            region_areas.push((alloc.name, rect, alloc.mode));
694	            y += alloc.height;
695	        }
696	
697	        // 4. Render each region, passing DegradeMode to components
698	        for &(name, rect, mode) in &region_areas {
699	            if rect.height == 0 {
700	                continue;
701	            }
702	            match name {
703	                "header" => {
704	                    self.render_header(frame, rect, hits);
705	                }
706	                "detection" => {
707	                    self.render_detections(frame, rect, mode);
708	                }
709	                "steps" => {
710	                    self.render_step_templates(frame, rect, hits, mode);
711	                }
712	                "summary" => {
713	                    self.render_summary(frame, rect, mode);
714	                }
715	                "footer" => {
716	                    let binding_set = self.bindings();
717	                    let footer_hints: Vec<KeyHint> = binding_set
718	                        .footer_bindings()
719	                        .iter()
720	                        .map(|b| KeyHint::new(b.key_label, b.description))
721	                        .collect();
722	                    let footer = FooterWidget::new(footer_hints);
723	                    footer.render(rect, frame.buffer_mut(), &self.theme);
724	                }
725	                _ => {}
726	            }
727	        }
728	
729	        // 5. Render help overlay on top of everything
730	        if self.show_help {
731	            self.render_help_overlay(frame, area);
732	        }
733	    }
734	
735	    fn bindings(&self) -> BindingSet {
736	        let mut set = BindingSet::new();
737	        set.add(bindings::NAVIGATE);
738	        set.add(bindings::TOGGLE);
739	        set.add(bindings::CONFIRM);
740	        set.add(bindings::CANCEL);
741	        set.add(bindings::QUIT);
742	        set.add(bindings::HELP);
743	        set
744	    }
745	
746	    fn handle_action(&mut self, action: Action, _state: &mut AppState) -> ScreenResult {
747	        // When help is showing, Help toggles it off; any other action dismisses it
748	        if self.show_help {
749	            self.show_help = false;
750	            return ScreenResult::Continue;
751	        }
752	
753	        match action {
754	            Action::Quit | Action::Cancel => {
755	                self.cancelled = true;
756	                ScreenResult::Quit
757	            }
758	            Action::Up => {
759	                self.move_selection(-1);
760	                ScreenResult::Continue
761	            }
762	            Action::Down => {
763	                self.move_selection(1);
764	                ScreenResult::Continue
765	            }
766	            Action::Toggle => {
767	                self.toggle_selection();
768	                ScreenResult::Continue
769	            }
770	            Action::Confirm => {
771	                self.completed = true;
772	                ScreenResult::Quit
773	            }
774	            Action::ScrollUp => {
775	                self.move_selection(-1);
776	                ScreenResult::Continue
777	            }
778	            Action::ScrollDown => {
779	                self.move_selection(1);
780	                ScreenResult::Continue
781	            }
782	            Action::Help => {
783	                self.show_help = true;
784	                ScreenResult::Continue
785	            }
786	            _ => ScreenResult::Continue,
787	        }
788	    }
789	
790	    fn handle_click(
791	        &mut self,
792	        action: Action,
793	        index: Option<usize>,
794	        click: ClickBehavior,
795	        state: &mut AppState,
796	    ) -> ScreenResult {
797	        match click {
798	            ClickBehavior::Fire => self.handle_action(action, state),
799	            ClickBehavior::FocusThenFire => {
800	                if let Some(idx) = index {
801	                    if idx == self.selected_index {
802	                        // Already focused — fire the action (toggle)
803	                        self.handle_action(action, state)
804	                    } else {
805	                        // Focus first
806	                        self.selected_index = idx;
807	                        self.ensure_visible();
808	                        ScreenResult::Continue
809	                    }
810	                } else {
811	                    ScreenResult::Continue
812	                }
813	            }
814	            ClickBehavior::FocusOnly => {
815	                if let Some(idx) = index {
816	                    self.selected_index = idx;
817	                    self.ensure_visible();
818	                }
819	                ScreenResult::Continue
820	            }
821	        }
822	    }
823	}
