89	            SkipReason::UserDeclined => "Skipped",
90	            SkipReason::SensitiveDeclined => "Skipped (declined sensitive step)",
91	            SkipReason::RequirementNotMet => "Skipped (requirement not met)",
92	        }
93	    }
