/// Returns true when `TERM=dumb`.
///
/// Dumb terminals don't support cursor movement, so interactive redraws
/// (clear-and-repaint cycles) produce garbage output. When true, prompts
/// render forward-only and `clear_lines` becomes a no-op.
pub(crate) fn is_dumb_term() -> bool {
    std::env::var("TERM").map(|v| v == "dumb").unwrap_or(false)
}

use crate::error::Result;
use indicatif::ProgressBar;

/// Output methods for displaying messages, warnings, errors, and hints.
pub trait OutputWriter {
    /// Display a message to the user.
    fn message(&mut self, msg: &str);

    /// Display a success message.
    fn success(&mut self, msg: &str);

    /// Display a warning message.
    fn warning(&mut self, msg: &str);

    /// Display an error message.
    fn error(&mut self, msg: &str);

    /// Show a contextual hint to the user.
    fn show_hint(&mut self, hint: &str) {
        self.message(hint);
    }

    /// Show a bordered error block with command, output, and optional hint.
    ///
    /// `indent` is the column at which the block should align (typically the
    /// step number width, so error content lines up under the step name).
    /// Implementations that don't render a visual box may ignore it.
    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
        let _ = indent;
        self.error(command);
        if !output.is_empty() {
            self.message(output);
        }
        if let Some(h) = hint {
            self.show_hint(h);
        }
    }
}

